/**
 * cfg-theme — host half.
 *
 * The palette override is a browser-only stylesheet. Its artifact is this
 * package's client bundle, `lib/client.js`, generated by
 * `cfg update dsh-theme` from `lib/client.js.tera` (registry:
 * cfg/templates.toml). The host half exists because a client bundle is only
 * served for a package whose host plugin is mounted in the composition, and
 * it registers nothing.
 */

/** Cordis plugin name; the client bundle registers under the same id. */
export const name = "cfg-theme";

/** Register nothing on the host. */
export function apply() {}
